  color: var(--muted);
  font-size: .83rem;
  font-weight: 650;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.desktop-nav a,
.mobile-panel a,
.contact-link {
  position: relative;
}

.desktop-nav a::after,
.contact-link::after {
  content: "";
