  padding: clamp(4rem, 10vw, 9rem) 0 clamp(2rem, 7vw, 5rem);
}

.hero h1,
.page-title,
.contact-title {
  margin: 0;
  font-family: var(--font-serif);
  font-weight: 800;
  line-height: .92;
  letter-spacing: -.075em;
}

.hero h1 {
  max-width: 13ch;
  font-size: clamp(4.2rem, 13vw, 15.5rem);
}

.eyebrow {
