  color: var(--muted);
  font-size: .78rem;
  font-weight: 750;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.media-showcase {
  display: grid;
  grid-template-columns: 1.18fr .82fr 1fr;
  gap: clamp(.8rem, 1.6vw, 1.6rem);
  align-items: end;
  padding: 0 0 clamp(5rem, 10vw, 10rem);
}

.media-block {
  min-height: clamp(24rem, 42vw, 42rem);
  border-radius: clamp(1.1rem, 2vw, 2rem);
  position: relative;
  overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(26, 26, 26, .08);
}

.media-block::after {
  content: attr(data-label);
  position: absolute;
  left: 1.25rem;
  bottom: 1rem;
  color: rgba(26, 26, 26, .58);
  font-size: .72rem;
  font-weight: 750;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.media-block:nth-child(1) {
  background: linear-gradient(135deg, #be6f56, #dfb194);
}

.media-block:nth-child(2) {
  min-height: clamp(18rem, 31vw, 31rem);
  background: linear-gradient(135deg, #9aa58c, #c3c5a8);
}

.media-block:nth-child(3) {
  min-height: clamp(28rem, 48vw, 46rem);
  background: linear-gradient(135deg, #d4b87f, #ead7ad);
}

.client-marquee {
  margin: 0 calc(clamp(1.25rem, 4vw, 4rem) * -1);
  padding: clamp(3rem, 7vw, 6.5rem) 0;
  border-block: 1px solid var(--line);
  overflow: hidden;
}

.marquee-row {
  display: flex;
  width: max-content;
  will-change: transform;
  animation: marquee-left 34s linear infinite;
}

.marquee-row + .marquee-row { margin-top: clamp(.45rem, 1.2vw, .9rem); }
.marquee-row.reverse { animation-name: marquee-right; animation-duration: 39s; }
.marquee-row.slow { animation-duration: 44s; }

.marquee-track {
  display: flex;
  align-items: baseline;
  gap: clamp(1.25rem, 3vw, 3rem);
  padding-right: clamp(1.25rem, 3vw, 3rem);
  font-family: var(--font-serif);
  font-size: clamp(3rem, 8vw, 9rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -.06em;
  white-space: nowrap;
}

.marquee-track span::after {
  content: "◦";
  margin-left: clamp(1.25rem, 3vw, 3rem);
  color: var(--terracotta);
  font-family: var(--font-sans);
  font-size: .48em;
  vertical-align: .16em;
}

@keyframes marquee-left {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-50%, 0, 0); }
}

@keyframes marquee-right {
  from { transform: translate3d(-50%, 0, 0); }
  to { transform: translate3d(0, 0, 0); }
}

.about-section,
.philosophy,
.clients-heading {
  padding: clamp(5rem, 11vw, 11rem) 0;
}

.about-grid,
.philosophy-grid,
.service-row {
  display: grid;
  grid-template-columns: minmax(10rem, .8fr) minmax(0, 1.55fr);
  gap: clamp(2rem, 8vw, 10rem);
}

.section-kicker {
  margin: .45rem 0 0;
  color: var(--muted);
  font-size: .76rem;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.about-copy,
.philosophy-copy,
.service-copy {
  max-width: 860px;
  font-size: clamp(1.45rem, 2.8vw, 3.15rem);
  line-height: 1.12;
  letter-spacing: -.045em;
}

.about-copy p,
.philosophy-copy p,
.service-copy p { margin: 0; }
.about-copy p + p,
.philosophy-copy p + p { margin-top: 1.15em; }

.editorial-page {
  padding: clamp(4rem, 8vw, 7rem) 0 clamp(6rem, 12vw, 12rem);
}

.letter-wrap {
  display: grid;
  grid-template-columns: minmax(8rem, .55fr) minmax(0, 780px) minmax(4rem, .45fr);
  gap: clamp(1.5rem, 5vw, 5rem);
}

.letter-meta {
  color: var(--muted);
  font-size: .82rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.letter h1 {
  margin: 0 0 clamp(2.5rem, 6vw, 5rem);
  font-family: var(--font-serif);
  font-size: clamp(4.4rem, 11vw, 11.5rem);
  font-weight: 800;
  line-height: .9;
  letter-spacing: -.075em;
}

.letter p {
  margin: 0;
  font-family: var(--font-serif);
  font-size: clamp(1.45rem, 2.4vw, 2.05rem);
  line-height: 1.42;
  letter-spacing: -.02em;
}

.letter p + p { margin-top: 1.25em; }

.philosophy-lede {
  margin: 0 0 clamp(3rem, 7vw, 6rem);
  max-width: 11ch;
  font-family: var(--font-serif);
  font-size: clamp(4rem, 11vw, 12.5rem);
  font-weight: 800;
  line-height: .9;
  letter-spacing: -.075em;
}

.divider {
  height: 1px;
  background: var(--line);
}

.services-list {
  padding: clamp(5rem, 10vw, 10rem) 0 clamp(6rem, 12vw, 12rem);
}

.services-question {
  margin: 0 0 clamp(4rem, 8vw, 7rem);
  max-width: 15ch;
  font-family: var(--font-serif);
  font-size: clamp(3.8rem, 9vw, 9.5rem);
  font-weight: 800;
  line-height: .92;
  letter-spacing: -.07em;
}

.service-row {
  padding: clamp(2.5rem, 5vw, 4.5rem) 0;
  border-top: 1px solid var(--line);
}

.service-row:last-child { border-bottom: 1px solid var(--line); }

.service-title {
  margin: 0;
  font-family: var(--font-serif);
  font-size: clamp(2.2rem, 5vw, 5.25rem);
  font-weight: 800;
  line-height: .95;
  letter-spacing: -.06em;
}

.service-copy {
  font-size: clamp(1.25rem, 2.2vw, 2.2rem);
  line-height: 1.18;
}

.page-title {
  max-width: 9ch;
  font-size: clamp(5.4rem, 16vw, 17rem);
}

.clients-heading {
  display: grid;
  min-height: 55vh;
  align-items: end;
}

.clients-subtitle {
  max-width: 550px;
  margin: 1.5rem 0 0 auto;
  color: var(--muted);
  font-size: clamp(1rem, 1.35vw, 1.3rem);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
  margin-bottom: clamp(5rem, 10vw, 10rem);
}

.client-card {
  min-height: 18rem;
  padding: clamp(1.5rem, 3vw, 3rem);
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.client-card h2 {
  margin: 0 0 1.1rem;
  font-family: var(--font-serif);
  font-size: clamp(2rem, 3.2vw, 4rem);
  font-weight: 800;
  line-height: .95;
  letter-spacing: -.055em;
}

.client-card p {
  margin: 0;
  max-width: 34ch;
  color: var(--muted);
  font-size: clamp(.98rem, 1.1vw, 1.08rem);
  line-height: 1.55;
}

.contact-main {
  min-height: calc(100vh - 6rem);
  display: grid;
  align-items: center;
  padding: clamp(2rem, 5vw, 5rem) 0 clamp(4rem, 8vw, 8rem);
}

.contact-title {
  text-align: center;
  font-size: clamp(5rem, 24vw, 25rem);
}

.contact-links {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(1.25rem, 4vw, 4rem);
  margin-top: clamp(2rem, 5vw, 4.5rem);
  color: var(--muted);
  font-size: clamp(1rem, 1.5vw, 1.35rem);
  font-weight: 700;
  letter-spacing: .04em;
}

.site-footer {
  padding: 2rem clamp(1.25rem, 4vw, 4rem);
  color: var(--muted);
  font-size: .8rem;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .001ms !important;
  }
}

@media (max-width: 900px) {
  .desktop-nav { display: none; }
  .menu-toggle { display: block; }
  .media-showcase { grid-template-columns: 1fr; }
  .media-block,
  .media-block:nth-child(2),
  .media-block:nth-child(3) { min-height: 62vw; }
  .about-grid,
  .philosophy-grid,
  .service-row,
  .letter-wrap { grid-template-columns: 1fr; }
  .letter-meta { order: -1; }
  .clients-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 620px) {
  body { font-size: 15px; }
  .site-header { padding: 1rem 1.1rem; }
  .page-shell { padding-inline: 1.1rem; }
  .hero { min-height: 72vh; }
  .hero h1 { font-size: clamp(4rem, 18vw, 7rem); }
  .about-copy,
  .philosophy-copy,
  .service-copy { font-size: 1.45rem; line-height: 1.22; }
  .clients-grid { grid-template-columns: 1fr; border-left: 0; }
  .client-card { border-right: 0; min-height: auto; }
  .contact-main { min-height: calc(100vh - 4.8rem); }
  .contact-links { flex-direction: column; align-items: center; }
}
