  padding: clamp(2rem, 5vw, 5rem) 0 clamp(4rem, 8vw, 8rem);
}

.contact-title {
  text-align: center;
  font-size: clamp(5rem, 24vw, 25rem);
}

.contact-links {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(1.25rem, 4vw, 4rem);
  margin-top: clamp(2rem, 5vw, 4.5rem);
  color: var(--muted);
  font-size: clamp(1rem, 1.5vw, 1.35rem);
  font-weight: 700;
  letter-spacing: .04em;
}

.site-footer {
  padding: 2rem clamp(1.25rem, 4vw, 4rem);
  color: var(--muted);
  font-size: .8rem;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .001ms !important;
  }
}

@media (max-width: 900px) {
  .desktop-nav { display: none; }
  .menu-toggle { display: block; }
  .media-showcase { grid-template-columns: 1fr; }
  .media-block,
  .media-block:nth-child(2),
  .media-block:nth-child(3) { min-height: 62vw; }
  .about-grid,
  .philosophy-grid,
  .service-row,
  .letter-wrap { grid-template-columns: 1fr; }
  .letter-meta { order: -1; }
  .clients-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 620px) {
  body { font-size: 15px; }
  .site-header { padding: 1rem 1.1rem; }
  .page-shell { padding-inline: 1.1rem; }
  .hero { min-height: 72vh; }
  .hero h1 { font-size: clamp(4rem, 18vw, 7rem); }
  .about-copy,
  .philosophy-copy,
  .service-copy { font-size: 1.45rem; line-height: 1.22; }
  .clients-grid { grid-template-columns: 1fr; border-left: 0; }
  .client-card { border-right: 0; min-height: auto; }
  .contact-main { min-height: calc(100vh - 4.8rem); }
  .contact-links { flex-direction: column; align-items: center; }
}
